int main(int argc,char**argv)try{if(argc!=2)return 2;const std::filesystem::path output=argv[1];std::filesystem::create_directories(output);Document doc;worker_gate::Guard guard;auto scene=fixture();doc.replace(scene.snapshot());const auto before=doc.copy_scene().encode();const auto one=output/"running.glb",two=output/"queued.glb",project=output/"ordered.dsculpt";seed(one);seed(two);const auto old=read(one);worker_gate::arm();auto running=doc.export_asset(one);check(worker_gate::wait(),"Actual HDR export FileJob reaches durable temporary fsync before atomic publication");auto queued=doc.export_asset(two);auto saved=doc.save_async(project);check(doc.frame().state->pending_exports==2&&doc.frame().state->can_cancel_asset,"Actual pending native HDR exports expose shared cancellation independently of the following Save");Hand hand(doc);hand.send(0,0,true);hand.send();hand.sector(8);hand.sector(9);hand.sector(6);check(doc.frame().state->menu_page==12&&doc.frame().state->menu_enabled[5],"Actual controller reaches enabled Cancel on the shared work page");hand.sector(5);worker_gate::release();check(cancelled(std::move(running))&&cancelled(std::move(queued)),"Controller Cancel reaches both running and queued actual HDR FileJobs");complete(std::move(saved));check(read(one)==old&&read(two)==old&&Scene::load(project).encode()==before&&doc.copy_scene().encode()==before,"Cancelled HDR files preserve prior bytes, exact ordered Save, source/history and current native scene");complete(doc.export_asset(one));auto native=extract_native_emission(read(one));check(native&&native->encode()==before&&!doc.frame().state->pending_exports,"Actual native retry produces exact full-scene HDR package and retires export status");auto edited=doc.copy_scene();auto &object=edited.object(3);auto material=object.material;material.emissive={.1f,.2f,.3f};doc.object_properties(object.id,object.name,object.visible,object.locked,object.transform,material);check(doc.undo()&&doc.copy_scene().encode()==before&&doc.redo(),"Ordinary native one-Undo/Redo remains exact after HDR export cancellation/retry");complete(doc.save_async(output/"after-edit.dsculpt"));check(Scene::load(output/"after-edit.dsculpt").encode()==doc.copy_scene().encode(),"Accepted subsequent native authoring saves/restarts exactly after HDR worker recovery");Scene avatar;append_humanoid(avatar,humanoid_baseline_defaults("vroid-beta-female"),"Female",{},64);const auto selected=std::find_if(avatar.objects().begin(),avatar.objects().end(),[](const auto &value){return bool(value.appearance)&&value.mesh_active&&bool(value.painted);});check(selected!=avatar.objects().end(),"Avatar fixture selects an actual source-painted part rather than the default SDF");auto &part=avatar.object(selected->id);part.painted=part.painted->snapshot();Brush brush;brush.from=brush.to=part.painted->mesh().positions.front();brush.normal={0,0,1};brush.radius=5;brush.strength=.7f;PaintSettings settings;settings.channel=PaintChannel::Emission;settings.emission_units=PaintEmissionUnits::Physical;settings.emission={10000,.005f,.0003f};settings.front_only=false;part.painted->begin_stroke();part.painted->stamp(brush,settings);check(part.painted->end_stroke(),"Real nineteen-part avatar receives physical ink before native Avatar FileJob");doc.replace(avatar.snapshot());const auto avatar_before=doc.copy_scene().encode();const auto vrm=output/"native-avatar.vrm",avatar_project=output/"avatar-ordered.dsculpt";seed(vrm);const auto prior=read(vrm);worker_gate::arm();auto avatar_job=doc.export_asset(vrm,AssetExportFormat::Avatar);check(worker_gate::wait(),"Real HDR Avatar FileJob reaches actual atomic durable-write boundary");auto avatar_save=doc.save_async(avatar_project);doc.cancel_background_work();worker_gate::release();check(cancelled(std::move(avatar_job)),"Shared native Cancel reaches actual running HDR Avatar writer");complete(std::move(avatar_save));check(read(vrm)==prior&&Scene::load(avatar_project).encode()==avatar_before&&doc.copy_scene().encode()==avatar_before,"Cancelled Avatar export preserves old bytes and exact following native Save/source history");complete(doc.export_asset(vrm,AssetExportFormat::Avatar));auto avatar_restored=extract_native_emission(read(vrm));std::vector<uint64_t> exported_parts;for(const auto &o:avatar.objects())if(o.appearance)exported_parts.push_back(o.id);const auto exact_avatar=detail::emission_export_subset(avatar,exported_parts).encode();check(exported_parts.size()==19&&avatar_restored&&avatar_restored->encode()==exact_avatar&&doc.copy_scene().encode()==avatar_before,"Actual Avatar FileJob retry exports exactly nineteen authenticated avatar parts/source/rig/morphs and excludes unrelated default SDF while current Scene remains exact");auto v1=worker_v1(output/"worker-v1-source.vrm");check(v1.objects.size()==2,"Independent valid VRM1 source imports two real native instances for FileJob proof");v1.scene.select(v1.objects.front());auto &v1_part=v1.scene.object(v1.objects.front());v1_part.painted=v1_part.painted->snapshot();brush.from=brush.to=v1_part.painted->mesh().positions.front();v1_part.painted->begin_stroke();v1_part.painted->stamp(brush,settings);check(v1_part.painted->end_stroke(),"Actual VRM1 instance receives native physical ink");doc.replace(v1.scene.snapshot());check(doc.frame().state->can_export_avatar,"Validated actual VRM1 metadata independently enables native Avatar command");const auto v1_before=doc.copy_scene().encode();const auto v1_path=output/"native-v1.vrm",v1_project=output/"native-v1-ordered.dsculpt";auto v1_export=doc.export_asset(v1_path,AssetExportFormat::Avatar);auto v1_save=doc.save_async(v1_project);complete(std::move(v1_export));complete(std::move(v1_save));auto v1_restored=extract_native_emission(read(v1_path));check(v1_restored&&v1_restored->encode()==detail::emission_export_subset(v1.scene,v1.objects).encode()&&Scene::load(v1_project).encode()==v1_before&&doc.copy_scene().encode()==v1_before,"Actual VRM1 Avatar FileJob preserves exact native subset, raw source, following full Save/restart and unchanged scene");std::cout<<"HDR actual native export worker: "<<checks<<" checks\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}
